package edu.smartstudy.focus;
import edu.smartstudy.planning.*;import edu.smartstudy.user.UserRepository;import jakarta.validation.Valid;import jakarta.validation.constraints.Positive;import java.util.*;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/focus/sessions")public class FocusSessionController{private final FocusSessionRepository sessions;private final UserRepository users;private final StudyTaskRepository tasks;public FocusSessionController(FocusSessionRepository sessions,UserRepository users,StudyTaskRepository tasks){this.sessions=sessions;this.users=users;this.tasks=tasks;}private Long owner(Authentication a){return users.findByEmailIgnoreCase(a.getName()).orElseThrow().getId();}public record StartRequest(@Positive Long taskId){}@GetMapping public List<FocusSession> history(Authentication a){return sessions.findTop30ByStudentIdOrderByStartedAtDesc(owner(a));}@GetMapping("/active")public ResponseEntity<?> active(Authentication a){return sessions.findFirstByStudentIdAndStatusInOrderByStartedAtDesc(owner(a),List.of("ACTIVE","PAUSED")).<ResponseEntity<?>>map(ResponseEntity::ok).orElseGet(()->ResponseEntity.noContent().build());}@PostMapping public ResponseEntity<?> start(@RequestBody(required=false) StartRequest request,Authentication a){Long student=owner(a);if(sessions.findFirstByStudentIdAndStatusInOrderByStartedAtDesc(student,List.of("ACTIVE","PAUSED")).isPresent())return ResponseEntity.status(409).body(Map.of("error","Finish or resume your current focus session first."));Long taskId=request==null?null:request.taskId();if(taskId!=null&&tasks.findByIdAndStudentId(taskId,student).isEmpty())return ResponseEntity.notFound().build();return ResponseEntity.status(201).body(sessions.save(new FocusSession(student,taskId)));}@PatchMapping("/{id}/pause")public ResponseEntity<?> pause(@PathVariable Long id,Authentication a){return update(id,a,FocusSession::pause);}@PatchMapping("/{id}/resume")public ResponseEntity<?> resume(@PathVariable Long id,Authentication a){return update(id,a,FocusSession::resume);}@PostMapping("/{id}/finish")public ResponseEntity<?> finish(@PathVariable Long id,Authentication a){return update(id,a,FocusSession::finish);}private ResponseEntity<?> update(Long id,Authentication a,java.util.function.Consumer<FocusSession> action){return sessions.findByIdAndStudentId(id,owner(a)).<ResponseEntity<?>>map(s->{action.accept(s);return ResponseEntity.ok(sessions.save(s));}).orElseGet(()->ResponseEntity.notFound().build());}}
